def get_config():
    with open("config.json", "r") as f:
        return json.load(f)


def set_secret_key(secret_key):
    config = get_config()
    config["secrets"].append({"id": secret_key["id"], "value": secret_key["value"]})

    with open("config.json", "w") as f:
        json.dump(config, f)


def del_secret_key(secret_key_id):
    config = get_config()
    if not config["secrets"]:
        return

    for i, secret in enumerate(config["secrets"]):
        if secret["id"] == secret_key_id:
            config["secrets"].pop(i)
            break

    with open("config.json", "w") as f:
        json.dump(config, f)

